const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const longitude = -81.97068176434179; // Corrected typo from -81.81.97068176434179
  const latitude = 38.07594286088219;
  const point = ee.Geometry.Point(longitude, latitude);

  const startYear = 1984;
  const endYear = 2009;

  // Hansen Global Forest Change data collection is UMD/hansen/global_forest_change_YYYY_vV
  // The 'lossyear' band indicates the year of forest loss (1=2001, ..., 23=2023).
  // We are interested in loss between 1984 and 2009.
  // The GFC dataset starts tracking loss from 2001. So, we need to check for lossyear values
  // corresponding to years 2001 through 2009.
  // lossyear_index = year - 2000
  const minLossYearIndex = Math.max(1, startYear - 2000); // GFC data starts from 2001 (index 1)
  const maxLossYearIndex = endYear - 2000;

  // 2. Data Acquisition
  const gfc = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // Extract relevant bands
  const treeCover2000 = gfc.select('treecover2000'); // Tree cover percentage in 2000
  const lossYear = gfc.select('lossyear');           // Year of gross forest cover loss

  // Define forest as >= 10% tree cover in 2000
  const forestThreshold = 10;
  const forestMask = treeCover2000.gte(forestThreshold);

  // Mask out non-forest areas based on 2000 tree cover
  const lossYearMasked = lossYear.updateMask(forestMask);

  // Calculate statistics at the point
  // Use a small scale to sample the pixel value directly at the point
  const scale = 30; // GFC resolution is 30m

  let treeCoverValue, lossYearValue;
  try {
    const stats = await ee.Image.cat(treeCover2000, lossYearMasked)
      .reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: point,
        scale: scale,
        maxPixels: 1e9
      })
      .getInfo();

    treeCoverValue = stats['treecover2000'];
    lossYearValue = stats['lossyear']; // This will be null if no forest initially or no loss within the dataset coverage
  } catch (e) {
    console.log(`Error during reduceRegion: ${e}`);
    console.log("C3"); // Calculation Failure due to GEE error
    return;
  }

  // 3. Validation & Final Answer
  if (treeCoverValue === null || lossYearValue === null) {
    // This could mean the point is outside the dataset coverage or invalid data.
    // However, if treeCoverValue is valid but lossYearValue is null, it typically means no loss.
    // For robust check, ensure treeCoverValue is present first.
    if (treeCoverValue === null) {
      console.log("Tree cover data not found at location.");
      console.log("C3"); // Calculation Failure (could be out of bounds for GFC dataset)
      return;
    }
  }

  // Determine if deforestation occurred within the specified period
  // We consider deforestation if:
  // 1. There was forest cover in 2000 (treeCoverValue >= 10%).
  // 2. Loss occurred (lossYearValue is not 0 and not null).
  // 3. The lossYearValue corresponds to a year between 2001 (minLossYearIndex) and 2009 (maxLossYearIndex).

  const wasForest = treeCoverValue !== null && treeCoverValue >= forestThreshold;
  const occurredLoss = lossYearValue !== null && lossYearValue > 0;
  const lossInPeriod = occurredLoss &&
                       lossYearValue >= minLossYearIndex &&
                       lossYearValue <= maxLossYearIndex;

  const actualLossYear = lossInPeriod ? (2000 + lossYearValue) : "N/A";

  console.log(`Location: (${latitude}, ${longitude})`);
  console.log(`Tree cover in 2000: ${treeCoverValue !== null ? treeCoverValue.toFixed(2) + '%' : 'N/A'}`);
  console.log(`Loss year index (1=2001, 9=2009): ${lossYearValue !== null ? lossYearValue : 'N/A'}`);
  console.log(`Deforestation period: ${startYear}-${endYear} (GFC index: ${minLossYearIndex}-${maxLossYearIndex})`);
  console.log(`Loss detected in period: ${lossInPeriod}`);
  console.log(`Actual loss year: ${actualLossYear}`);

  if (!wasForest) {
    console.log("No significant tree cover in 2000 to be deforested.");
    console.log("B"); // No deforestation as there was no forest to lose
  } else if (lossInPeriod) {
    console.log("A"); // Deforestation occurred
  } else {
    console.log("B"); // No deforestation in the specified period
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
